-- 8-week fight conditioning programs (GRIZZ, 2026-10-14) for Boxing, Muay
-- Thai, MMA, BJJ and Wrestling: strength and conditioning that sits alongside
-- the athlete's skill training, with recovery built in.
--
-- Week layout (days 1-7 = Mon-Sun): Mon Strength & Power A, Tue skill only,
-- Wed Fight conditioning, Thu Active recovery (zone 2 + mobility), Fri skill
-- only, Sat Strength & Power B, Sun full rest. Weeks 1-3 build (sets and
-- rounds go up each week), week 4 is a recovery week (half the sets), weeks
-- 5-7 are fight-specific (contrast/explosive lifts, conditioning shaped to
-- each sport's round length), week 8 is a fight/test week (half the volume,
-- same intensity).
--
-- Based on the combat-sport S&C research: concurrent training with
-- strength 2x a week maintains and builds force without hurting skill work;
-- the sports are mostly aerobic with repeated high-intensity bursts, so each
-- camp builds an aerobic base, then sport-specific interval work; neck and
-- grip work for injury resilience; tapers cut volume by about half and keep
-- intensity. No overhead pressing (GRIZZ's rule for built-ins).
--
-- Only inserted when a built-in program with the same name isn't there yet.

create or replace function pg_temp.add_fight_program(p_name text, p_description text, p_nutrition text, p_warm_up text, p_tpl jsonb)
returns void language plpgsql as $f$
declare
  prog uuid;
  titles text[] := '{}';
  w int;
  ph text;
  wp int;
  half boolean;
  tag text;
  d text;
  r jsonb;
  i int;
  n int;
begin
  if exists (select 1 from public.programs where trainer_id is null and name = p_name) then
    return;
  end if;
  for w in 1..8 loop
    tag := case w when 4 then ' (recovery week)' when 8 then ' (fight week)' else '' end;
    titles := titles || array['Strength & Power A' || tag, 'Recovery: skill training only', 'Fight conditioning' || tag,
      'Active recovery: zone 2 + mobility' || tag, 'Recovery: skill training only', 'Strength & Power B' || tag, 'Full rest'];
  end loop;
  insert into public.programs (trainer_id, name, kind, place, weeks, description, nutrition, warm_up, day_titles)
  values (null, p_name, 'weekly', 'gym', 8, p_description, p_nutrition, p_warm_up, titles)
  returning id into prog;
  for w in 1..8 loop
    ph := case when w <= 4 then 'p1' else 'p2' end;
    half := w in (4, 8);
    wp := case when w <= 3 then w when w between 5 and 7 then w - 4 else 1 end;
    -- Strength & Power A (Mon), Fight conditioning (Wed), Strength & Power B (Sat):
    -- sets marked to grow go up by one in the 2nd and 3rd week of a phase;
    -- recovery and fight weeks halve every block.
    foreach d in array array['1', '3', '6'] loop
      i := 0;
      for r in select * from jsonb_array_elements(p_tpl -> ph -> d) loop
        i := i + 1;
        n := (r->>1)::int;
        n := case when half then greatest(1, ceil(n / 2.0)::int) when (r->>5)::boolean then n + wp - 1 else n end;
        insert into public.program_exercises (program_id, week_number, day_number, sort_order, exercise_id, exercise_name, sets, reps, rest_seconds, kind)
        values (prog, w, d::smallint, i,
          case when r->>4 = 'exercise' then (select e.id from public.exercises e where e.name = r->>0 order by e.sort_order limit 1) end,
          r->>0, n, r->>2, (r->>3)::smallint, r->>4);
      end loop;
    end loop;
    -- Active recovery (Thu): the same easy session every week, shorter ride in fight week.
    i := 0;
    for r in select * from jsonb_array_elements(p_tpl -> 'rec') loop
      i := i + 1;
      insert into public.program_exercises (program_id, week_number, day_number, sort_order, exercise_id, exercise_name, sets, reps, rest_seconds, kind)
      values (prog, w, 4, i,
        (select e.id from public.exercises e where e.name = r->>0 order by e.sort_order limit 1),
        r->>0, (r->>1)::smallint,
        case when w = 8 and i = 1 then '20 min zone 2: easy, nose-breathing pace' else r->>2 end,
        (r->>3)::smallint, r->>4);
    end loop;
  end loop;
  if exists (select 1 from public.program_exercises pe where pe.program_id = prog and pe.kind = 'exercise' and pe.exercise_id is null) then
    raise exception 'an exercise in % is not in the library', p_name;
  end if;
end $f$;

do $$
declare
  nutrition text := 'Fight training burns a lot, so eat enough to recover: protein 1.8-2.2 g per kg of bodyweight a day, split over 4-5 meals, and carbs of 4-6 g/kg on hard training days (rice, potatoes, sweet potato, fruit, pap), less on rest days. Eat a carb-and-protein meal 2-3 hours before training and another within 2 hours after, such as chicken with rice, eggs on toast, or maas with fruit and a banana. Drink 35-40 ml of water per kg a day plus 500-750 ml per hour of training, with electrolytes on sweaty days. If you have a weight class, stay within about 5-8% of it all camp and lose weight slowly (0.5-1% a week). Avoid big dehydration cuts: they wreck strength and are dangerous. Creatine monohydrate 3-5 g a day is safe and helps repeat efforts, but it adds 1-2 kg of water weight, so plan around weigh-ins.';
  warm_up text := 'RAMP warm-up, 10 minutes: 3-4 minutes skipping or easy bike; then leg swings, hip circles, world''s greatest stretch and band pull-aparts; then 2-3 fast efforts such as jumps, shadow boxing bursts or sprawls. Before the first lift, do 2-3 lighter ramp-up sets. On conditioning days, start the first round at 70% and build.';
  rec jsonb := '[["Steady State Ride",1,"30-40 min zone 2: easy, nose-breathing pace you could chat at",60,"exercise",false],["Dead Hang",3,"30 sec",30,"exercise",false],["Bird Dog",2,"8 each side, slow",30,"exercise",false],["Cossack Squat",2,"6 each side, slow and deep",30,"exercise",false],["Bodyweight Spinal Jefferson Curl",2,"8 slow, light",30,"exercise",false],["Glute Bridge",2,"12",30,"exercise",false]]'::jsonb;
begin
  perform pg_temp.add_fight_program('Fight Conditioning – Boxing', 'For Boxing: an 8-week strength and conditioning program that sits alongside your boxing training. It builds leg drive, rotational power through the hips and trunk, a strong upper back and neck, and the engine to keep punching hard in the late rounds. Each week has 2 strength and power sessions (Monday and Saturday), 1 fight conditioning session (Wednesday) and 1 active recovery session (Thursday: easy zone 2 cardio and mobility), with Tuesday and Friday kept for skill training only and Sunday as full rest. Weeks 1-3 build the base: heavier strength work and longer conditioning efforts, adding sets and rounds each week. Week 4 is a recovery week with half the work. Weeks 5-7 get fight-specific: faster, more explosive lifts and conditioning built around 3-minute rounds with 1 minute rest, again building each week. Week 8 is a fight week (or test week): half the volume with the same intensity, so you arrive fresh and sharp. Leave 1-2 reps in the tank on strength work, move fast on power work, and lift after skill training or at least 6 hours apart. If you had a hard sparring day, swap that day''s conditioning for the recovery session. Sleep 8-9 hours.',
    nutrition, warm_up, '{"p1":{"1":[["Trap Bar Deadlift",3,"4-6",150,"exercise",true],["Dumbbell Bulgarian Split Squat",3,"6-8 each leg",90,"exercise",false],["Pull-Up",3,"6-8",120,"exercise",true],["Single-Arm Landmine Press",3,"6-8 each arm",90,"exercise",false],["Pallof Press",3,"10 each side",45,"exercise",false],["Neck Curl",2,"15-20, light and slow",45,"exercise",false]],"3":[["Assault Bike",5,"3 min round at 7/10",60,"exercise",true],["Jump Rope",3,"2 min, light and quick",60,"exercise",false],["Plank",3,"40 sec",30,"exercise",false]],"6":[["Kettlebell Swing",4,"10 fast",90,"exercise",false],["Floor Press",3,"6-8",120,"exercise",true],["Single-Arm Dumbbell Row (Unilateral)",3,"8 each arm",90,"exercise",false],["Cable Wood Chopper",3,"10 each side",60,"exercise",false],["Single-Leg Romanian Deadlift",3,"8 each leg",90,"exercise",false],["Neck Extension",2,"15-20, light and slow",45,"exercise",false]]},"p2":{"1":[["Trap Bar Deadlift",4,"3-4 fast",180,"exercise",false],["Box Jump",4,"3, step down",90,"exercise",false],["Barbell Split Squat",3,"5 each leg",120,"exercise",false],["Weighted Pull-Up",3,"4-6",150,"exercise",true],["Single-Arm Landmine Press",3,"5 explosive each arm",90,"exercise",false],["Neck Curl",2,"15-20, light and slow",45,"exercise",false]],"3":[["Assault Bike",6,"3 min round: 15 sec sprint at the start of every minute",60,"exercise",true],["SkiErg",6,"20 sec all-out",40,"exercise",false],["Mountain Climber",3,"30 sec",30,"exercise",false]],"6":[["Kettlebell Swing",4,"8 explosive",90,"exercise",false],["Push-Up",4,"6 explosive, hands leave the floor",90,"exercise",false],["Chest-Supported Row",3,"6-8",90,"exercise",true],["Cable Standing Low-to-High Wood Chopper",3,"6 explosive each side",60,"exercise",false],["Single-Leg Romanian Deadlift",3,"6 each leg",90,"exercise",false],["Neck Extension",2,"15-20, light and slow",45,"exercise",false]]}}'::jsonb || jsonb_build_object('rec', rec));
  perform pg_temp.add_fight_program('Fight Conditioning – Muay Thai', 'For Muay Thai: an 8-week strength and conditioning program that sits alongside your muay thai training. It builds strong, mobile hips for kicks and knees, single-leg balance, a strong neck and trunk for the clinch, and the engine to keep kicking hard through five rounds. Each week has 2 strength and power sessions (Monday and Saturday), 1 fight conditioning session (Wednesday) and 1 active recovery session (Thursday: easy zone 2 cardio and mobility), with Tuesday and Friday kept for skill training only and Sunday as full rest. Weeks 1-3 build the base: heavier strength work and longer conditioning efforts, adding sets and rounds each week. Week 4 is a recovery week with half the work. Weeks 5-7 get fight-specific: faster, more explosive lifts and conditioning built around 3-minute rounds with 2 minutes rest, again building each week. Week 8 is a fight week (or test week): half the volume with the same intensity, so you arrive fresh and sharp. Leave 1-2 reps in the tank on strength work, move fast on power work, and lift after skill training or at least 6 hours apart. If you had a hard sparring day, swap that day''s conditioning for the recovery session. Sleep 8-9 hours.',
    nutrition, warm_up, '{"p1":{"1":[["Trap Bar Deadlift",3,"4-6",150,"exercise",true],["Barbell Step-Up Knee Drive",3,"6 each leg",90,"exercise",false],["Pull-Up",3,"6-8",120,"exercise",true],["Cossack Squat",3,"6 each side",60,"exercise",false],["Hip Adduction",3,"12-15",60,"exercise",false],["Neck Curl",2,"15-20, light and slow",45,"exercise",false]],"3":[["Shadow Boxing",5,"3 min round with kicks and knees at 7/10",120,"exercise",true],["Jump Rope",3,"2 min",60,"exercise",false],["Single-Leg Standing Calf Raise",3,"12-15 each leg",45,"exercise",false]],"6":[["Kettlebell Swing",4,"10 fast",90,"exercise",false],["Floor Press",3,"6-8",120,"exercise",true],["Seated Cable Row",3,"8-10",90,"exercise",false],["Single-Leg Romanian Deadlift",3,"8 each leg",90,"exercise",false],["Cable Wood Chopper",3,"10 each side",60,"exercise",false],["Neck Extension",2,"15-20, light and slow",45,"exercise",false]]},"p2":{"1":[["Trap Bar Deadlift",4,"3-4 fast",180,"exercise",false],["Box Jump",4,"3, step down",90,"exercise",false],["Barbell Front Rack Step-Up Knee Drive",3,"5 explosive each leg",120,"exercise",false],["Weighted Pull-Up",3,"4-6",150,"exercise",true],["Dumbbell Lateral Lunge",3,"6 each side",60,"exercise",false],["Neck Curl",2,"15-20, light and slow",45,"exercise",false]],"3":[["Shadow Boxing",5,"3 min fight-pace round: 10 fast knees or kicks every 30 sec",120,"exercise",true],["Assault Bike",6,"20 sec all-out",40,"exercise",false],["V-Up",3,"12",30,"exercise",false]],"6":[["Kettlebell Swing",4,"8 explosive",90,"exercise",false],["Push-Up",4,"6 explosive, hands leave the floor",90,"exercise",false],["Chest-Supported Row",3,"6-8",90,"exercise",true],["Cable Standing Low-to-High Wood Chopper",3,"6 explosive each side",60,"exercise",false],["Kettlebell Turkish Get-Up",3,"2 each side, slow",60,"exercise",false],["Neck Extension",2,"15-20, light and slow",45,"exercise",false]]}}'::jsonb || jsonb_build_object('rec', rec));
  perform pg_temp.add_fight_program('Fight Conditioning – MMA', 'For MMA: an 8-week strength and conditioning program that sits alongside your MMA training. It builds all-round strength for takedowns and scrambles, power for strikes, a strong neck and grip, and the engine to fight hard for three to five 5-minute rounds. Each week has 2 strength and power sessions (Monday and Saturday), 1 fight conditioning session (Wednesday) and 1 active recovery session (Thursday: easy zone 2 cardio and mobility), with Tuesday and Friday kept for skill training only and Sunday as full rest. Weeks 1-3 build the base: heavier strength work and longer conditioning efforts, adding sets and rounds each week. Week 4 is a recovery week with half the work. Weeks 5-7 get fight-specific: faster, more explosive lifts and conditioning built around 5-minute rounds with 1 minute rest, again building each week. Week 8 is a fight week (or test week): half the volume with the same intensity, so you arrive fresh and sharp. Leave 1-2 reps in the tank on strength work, move fast on power work, and lift after skill training or at least 6 hours apart. If you had a hard sparring day, swap that day''s conditioning for the recovery session. Sleep 8-9 hours.',
    nutrition, warm_up, '{"p1":{"1":[["Trap Bar Deadlift",4,"4-6",150,"exercise",true],["Front Squat",3,"5-6",150,"exercise",true],["Weighted Pull-Up",3,"5-6",150,"exercise",false],["Single-Arm Landmine Press",3,"6-8 each arm",90,"exercise",false],["Kettlebell Farmer''s Carry",3,"40 m heavy",90,"exercise",false],["Neck Curl",2,"15-20, light and slow",45,"exercise",false]],"3":[["Assault Bike",3,"1 min hard (round station 1)",0,"exercise",true],["Sled Push",3,"1 min, 20 m pushes back and forth",0,"exercise",true],["Burpee",3,"1 min, sprawl to stand",0,"exercise",true],["Battle Ropes",3,"1 min",0,"exercise",true],["Kettlebell Swing",3,"1 min, then rest",60,"exercise",true]],"6":[["Hang Power Clean",4,"3, crisp and fast",120,"exercise",false],["Floor Press",3,"6-8",120,"exercise",true],["Barbell Bent-Over Row",3,"6-8",120,"exercise",false],["Dumbbell Bulgarian Split Squat",3,"8 each leg",90,"exercise",false],["Pallof Press",3,"10 each side",45,"exercise",false],["Neck Extension",2,"15-20, light and slow",45,"exercise",false]]},"p2":{"1":[["Trap Bar Deadlift",4,"3 fast",180,"exercise",false],["Box Jump",4,"3, step down",90,"exercise",false],["Zercher Squat",3,"4-5",150,"exercise",false],["Weighted Pull-Up",4,"3-5",150,"exercise",false],["Single-Arm Landmine Press",3,"5 explosive each arm",90,"exercise",false],["Neck Curl",2,"15-20, light and slow",45,"exercise",false]],"3":[["Assault Bike",3,"1 min with a 15 sec sprint at the end",0,"exercise",true],["Sled Push",3,"1 min heavy pushes",0,"exercise",true],["Burpee",3,"1 min, fast sprawls",0,"exercise",true],["Sled Pull",3,"1 min hand-over-hand or walking back",0,"exercise",true],["Battle Ropes",3,"1 min all-out finish, then rest",60,"exercise",true]],"6":[["Hang Power Clean",4,"2, explosive",150,"exercise",false],["Push-Up",4,"6 explosive, hands leave the floor",90,"exercise",false],["Pendlay Row",3,"5 explosive",120,"exercise",false],["Cable Standing Low-to-High Wood Chopper",3,"6 explosive each side",60,"exercise",false],["Kettlebell Farmer''s Carry",3,"40 m heavy",90,"exercise",false],["Neck Extension",2,"15-20, light and slow",45,"exercise",false]]}}'::jsonb || jsonb_build_object('rec', rec));
  perform pg_temp.add_fight_program('Fight Conditioning – BJJ', 'For BJJ: an 8-week strength and conditioning program that sits alongside your BJJ training. It builds a big aerobic engine for long rolls, grip and pulling strength, strong hips and trunk, isometric strength for holding positions, and a resilient neck. Each week has 2 strength and power sessions (Monday and Saturday), 1 fight conditioning session (Wednesday) and 1 active recovery session (Thursday: easy zone 2 cardio and mobility), with Tuesday and Friday kept for skill training only and Sunday as full rest. Weeks 1-3 build the base: heavier strength work and longer conditioning efforts, adding sets and rounds each week. Week 4 is a recovery week with half the work. Weeks 5-7 get fight-specific: faster, more explosive lifts and conditioning built around 5- to 10-minute rolls, again building each week. Week 8 is a fight week (or test week): half the volume with the same intensity, so you arrive fresh and sharp. Leave 1-2 reps in the tank on strength work, move fast on power work, and lift after skill training or at least 6 hours apart. If you had a hard sparring day, swap that day''s conditioning for the recovery session. Sleep 8-9 hours.',
    nutrition, warm_up, '{"p1":{"1":[["Trap Bar Deadlift",3,"5-6",150,"exercise",true],["Goblet Squat",3,"8-10",90,"exercise",false],["Weighted Pull-Up",3,"5-6",150,"exercise",true],["Inverted Row",3,"8-10",90,"exercise",false],["Plate Pinch",3,"30 sec",60,"exercise",false],["Neck Curl",2,"15-20, light and slow",45,"exercise",false]],"3":[["Rowing Intervals",4,"6 min at threshold (7/10), like a hard roll",120,"exercise",true],["Kettlebell Farmer''s Carry",3,"40 m",60,"exercise",false],["Dead Hang",3,"as long as you can",60,"exercise",false]],"6":[["Kettlebell Turkish Get-Up",3,"2 each side, slow",60,"exercise",false],["Floor Press",3,"6-8",120,"exercise",false],["Chest-Supported Row",3,"8-10",90,"exercise",true],["Single-Leg Romanian Deadlift",3,"8 each leg",90,"exercise",false],["Hip Adduction",3,"12-15",60,"exercise",false],["Neck Extension",2,"15-20, light and slow",45,"exercise",false]]},"p2":{"1":[["Trap Bar Deadlift",4,"3-4 fast",180,"exercise",false],["Split Squat Isometric Hold",3,"30 sec each leg",60,"exercise",false],["Weighted Pull-Up",4,"4-5",150,"exercise",false],["Kettlebell Gorilla Row",3,"8 each arm",90,"exercise",false],["Wrist Roller",3,"up and down twice",60,"exercise",false],["Neck Curl",2,"15-20, light and slow",45,"exercise",false]],"3":[["Assault Bike",4,"6 min roll: 40 sec moderate, 20 sec hard, repeat",120,"exercise",true],["Sled Pull",4,"30 m hand-over-hand",60,"exercise",false],["Dead Hang",3,"as long as you can",60,"exercise",false]],"6":[["Kettlebell Swing",4,"10 fast",90,"exercise",false],["Push-Up",3,"10-12",60,"exercise",false],["Seal Row",3,"6-8",90,"exercise",true],["Kettlebell Turkish Get-Up",3,"2 each side",60,"exercise",false],["Pallof Press",3,"10 each side",45,"exercise",false],["Neck Extension",2,"15-20, light and slow",45,"exercise",false]]}}'::jsonb || jsonb_build_object('rec', rec));
  perform pg_temp.add_fight_program('Fight Conditioning – Wrestling', 'For Wrestling: an 8-week strength and conditioning program that sits alongside your wrestling training. It builds explosive hips for shots and lifts, strength in awkward positions, a strong neck, back and grip, and repeat-sprint fitness for high-pace periods. Each week has 2 strength and power sessions (Monday and Saturday), 1 fight conditioning session (Wednesday) and 1 active recovery session (Thursday: easy zone 2 cardio and mobility), with Tuesday and Friday kept for skill training only and Sunday as full rest. Weeks 1-3 build the base: heavier strength work and longer conditioning efforts, adding sets and rounds each week. Week 4 is a recovery week with half the work. Weeks 5-7 get fight-specific: faster, more explosive lifts and conditioning built around 2- to 3-minute periods, again building each week. Week 8 is a fight week (or test week): half the volume with the same intensity, so you arrive fresh and sharp. Leave 1-2 reps in the tank on strength work, move fast on power work, and lift after skill training or at least 6 hours apart. If you had a hard sparring day, swap that day''s conditioning for the recovery session. Sleep 8-9 hours.',
    nutrition, warm_up, '{"p1":{"1":[["Front Squat",4,"5-6",150,"exercise",true],["Trap Bar Deadlift",3,"5",150,"exercise",false],["Weighted Pull-Up",3,"5-6",150,"exercise",true],["Barbell Bent-Over Row",3,"6-8",120,"exercise",false],["Kettlebell Farmer''s Carry",3,"40 m heavy",90,"exercise",false],["Neck Curl",2,"15-20, light and slow",45,"exercise",false]],"3":[["Assault Bike",6,"2 min at 8/10",60,"exercise",true],["Sled Push",4,"20 m hard",60,"exercise",false],["Burpee",3,"10 fast sprawls",45,"exercise",false]],"6":[["Hang Power Clean",4,"3, crisp and fast",120,"exercise",false],["Floor Press",3,"6-8",120,"exercise",false],["Zercher Squat",3,"5-6",150,"exercise",true],["Single-Leg Romanian Deadlift",3,"8 each leg",90,"exercise",false],["Wrist Roller",3,"up and down twice",60,"exercise",false],["Neck Extension",2,"15-20, light and slow",45,"exercise",false]]},"p2":{"1":[["Power Clean",5,"2, explosive",150,"exercise",false],["Box Jump",4,"3, step down",90,"exercise",false],["Front Squat",4,"3-4",180,"exercise",false],["Weighted Pull-Up",4,"3-5",150,"exercise",false],["Kettlebell Farmer''s Carry",3,"40 m heavy",90,"exercise",false],["Neck Curl",2,"15-20, light and slow",45,"exercise",false]],"3":[["Sled Push",3,"20 sec sprint push (period start)",0,"exercise",true],["Burpee",3,"20 sec fast sprawls",0,"exercise",true],["Assault Bike",3,"40 sec hard",0,"exercise",true],["Battle Ropes",3,"20 sec all-out",0,"exercise",true],["Sled Pull",3,"40 sec, then rest",60,"exercise",true]],"6":[["Snatch Grip High Pull",4,"3 explosive",120,"exercise",false],["Push-Up",4,"6 explosive, hands leave the floor",90,"exercise",false],["Pendlay Row",3,"5 explosive",120,"exercise",false],["Zercher Squat",3,"4-5",150,"exercise",true],["Plate Pinch",3,"30 sec",60,"exercise",false],["Neck Extension",2,"15-20, light and slow",45,"exercise",false]]}}'::jsonb || jsonb_build_object('rec', rec));
end $$;
